          while ((temp = new BigInteger(256, randomGenerator)).equals(BigInteger.ZERO))
             ;
          LargePositives[i] = temp;

          while ((temp = new BigInteger(256, randomGenerator)).equals(BigInteger.ZERO))
             ;
          LargeNegatives[i] = temp.negate();
       }
    } 

