    public static void verifyDigits(byte[] pd, int offset, int precision)
    {
        boolean high4Bits = true;
        if (precision % 2 == 0)
        {
            high4Bits = false;
        }

        for (int i = offset; i < offset + precision / 2 + 1;)
        {
            if (high4Bits)
            {
                int comp = pd[i] & 0xF0;
                comp >>= 4;
                Assert.assertTrue(comp >= 0 && comp <= 9);
                high4Bits = !high4Bits;
            } else
            // !high4Bits
            {
                int comp = pd[i] & 0x0F;
                i++;
                Assert.assertTrue(comp >= 0 && comp <= 9);
                high4Bits = !high4Bits;
            }
        }
    }

