    }

    private int getRandomIntegerWithNHexDigits(int n)
    {
        assertTrue(n > 0 && n <= 8);
        int randomInt = 0;
        for (int k = 0; k < n; k++)
            randomInt = randomInt | (((randomGen.nextInt() >> k * 4) & 0x0f) << (n - k - 1) * 4);
        return randomInt < 0 ? randomInt * -1 : randomInt;
    }

    private int getRandomNumBytes()
    {
        int rn = randomGen.nextInt() % 5;
        return (rn < 0) ? rn * -1 : rn;
    }

