package net.openj9.test.management;

class BusyThread implements Runnable {
	long busyTime;

	// Constructor
	public BusyThread(int mSec) {
		busyTime = mSec * 1000000L;
	}

	// Invoke method
	public void run() {
		long startTime = System.nanoTime();
		while ((System.nanoTime() - startTime) < busyTime) {
			// do nothing
		}	
	}
}

