package net.openj9.test.management;

import java.util.Random;

class RandomNumber {
	public long generateRandomNumber(long start, long end){
		long seed = System.nanoTime();
		System.out.println("Seed value: " + seed);

		Random rand = new Random(seed);
		long randomValue = rand.nextLong();

		if(randomValue > start && randomValue < end)
			return randomValue;
		else
			return(generateRandomNumber(start, end));
	}
}

