class FibonacciSeriesOSMXBean implements Runnable {
	long limit;
	long result;

	public FibonacciSeriesOSMXBean(long limit) {
		this.limit = limit;
	}

	public void run() {

		long start = 1;
		long next = 1;
		long result = start;

		while( result < (limit*0.75) ) {
			long output = start + next;
			result = output;			
			start = next;
			next = output;
		}

		TestOperatingSystemMXBean.SHARED_RESULT = result;
	}
}

