	public void deleteDirectory(File directory) {
		if (directory.exists()) {
			File[] files = directory.listFiles();
			if (files != null) {
				for (File file : files) {
					if (file.isDirectory()) {
						deleteDirectory(file);
					} else {
						file.delete(); 
					}
				}
			}
			directory.delete(); 
		} else {
			System.out.println("Directory does not exist: " + directory.getAbsolutePath());
		}
	}

