public class LoaderSlaveMultiThread
{
	public final long OVERALL_TIME_LIMIT_IN_MILISECONDS = 10 * 60 * 1000; 
	public final long startTime = System.currentTimeMillis(); 

	public LoaderSlaveMultiThread()
	{
	}

	public static void main(String args[])
	{
		if(args.length == 0)
		{
			System.out.println("Usage: LoaderSlaveMultiThread <path of jar file eg. 10000med.jar> <MAX No. Threads>");
			return;
		}
		try
		{
			(new LoaderSlaveMultiThread()).run(args[0],Integer.parseInt(args[1]));

			// Print debug information: on Linux or AIX, run "ps v <pid>" on the JVM running the test
			String os = System.getProperty("os.name").toLowerCase(); 
			if ( os.contains("linux") || os.contains("aix")) { 
				String pid = ManagementFactory.getRuntimeMXBean().getName().split("@")[0];
				runSystemCmd("ps v " + pid); 
			}
		}
		catch(Exception e)
		{
			e.printStackTrace();
		}
	}

	private static void runSystemCmd(String cmd) {
		String s = null;

		try {
			Process p = Runtime.getRuntime().exec(cmd);
			BufferedReader stdInput = new BufferedReader(new InputStreamReader(p.getInputStream()));
			BufferedReader stdError = new BufferedReader(new InputStreamReader(p.getErrorStream()));

			System.out.println("stdout of command: " + cmd);
			while ((s = stdInput.readLine()) != null) {
			    System.out.println(s);
			}

			System.out.println("stderr of command: " + cmd);
			while ((s = stdError.readLine()) != null) {
			    System.out.println(s);
			}
		} catch (IOException e) {
			e.printStackTrace();
		}
	}

	public void run(String jarName, int threadsMAX)
		throws Exception
	{
		Counter cntr = new Counter(0);
		JarFile file = new JarFile(jarName);
		File jarFile = new File(file.getName());
		URL myURL = new URL("file", null, 0, jarFile.getCanonicalPath().replace('\\', '/'));
		URL[] myURLS = {myURL};
		URLClassLoader myCL = new URLClassLoader(myURLS);

		int start = 0, finish = 0;
		LinkedList<Thread> threads = new LinkedList<Thread>();

		for(Enumeration<JarEntry> entries = file.entries(); entries.hasMoreElements();)
		{
			// This check has been added to terminate the load test within 10 minutes 
			// keeping in mind that the test launches 5 processes to simultaneously run this load and 
			// the overall time it takes is especially slow on certain platforms (e.g. Windows)
			if ( (System.currentTimeMillis() - startTime) > OVERALL_TIME_LIMIT_IN_MILISECONDS ) {
				logMessage("Test duration expired - Ran a 10m load. Not Starting any more threads");
				break;
			}

			JarEntry entry = (JarEntry)entries.nextElement();
			String className = entry.getName();
			if(className.endsWith(".class"))
			{
				className = className.substring(0, className.length() - 6);
				className = className.replace('/', '.');

				LoaderThread lT = new LoaderThread(myCL, className, cntr);
				Thread t = new Thread(lT);
				finish++;
				threads.add(t);
				t.start();
			}
			if (finish - start == threadsMAX)
			{
				logMessage("--> Threads " + start + " to " + finish + " <--");
				start = finish;
				Iterator<Thread> threadsJoinI = threads.iterator();
				while (threadsJoinI.hasNext())
				{
					threadsJoinI.next().join();
				}
				threads = new LinkedList<Thread>();
			}
		}

		file.close();
	}

	public void logMessage(String message)
	{
		NumberFormat formatter = NumberFormat.getIntegerInstance();
		formatter.setMinimumIntegerDigits(2);
		Calendar c = Calendar.getInstance();
		System.out.println(formatter.format(c.get(Calendar.HOUR_OF_DAY)) + ":" + formatter.format(c.get(Calendar.MINUTE)) + ":" + formatter.format(c.get(Calendar.SECOND)) + " >> " + message);
	}

